package kz.zeroops.agent;
import com.fasterxml.jackson.databind.ObjectMapper; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.Instant; import java.util.*; import javax.crypto.*; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component;
@Component public class ManifestVerifier { private final byte[] key; private final ObjectMapper json; public ManifestVerifier(@Value("${agent.manifest-signing-key}")String secret,ObjectMapper json){this.json=json;key=secret.isBlank()?new byte[0]:Base64.getDecoder().decode(secret);} public Optional<AgentBoundary.Manifest> verify(String payload,String signature,long serverId){try{if(key.length<32)return Optional.empty();Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(key,"HmacSHA256"));String expected=Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(payload.getBytes(StandardCharsets.UTF_8)));if(!MessageDigest.isEqual(expected.getBytes(StandardCharsets.UTF_8),signature.getBytes(StandardCharsets.UTF_8)))return Optional.empty();Wire wire=json.readValue(Base64.getUrlDecoder().decode(payload),Wire.class);if(wire.version()!=2||wire.serverId()!=serverId)return Optional.empty();return Optional.of(new AgentBoundary.Manifest(String.valueOf(wire.deploymentId()),String.valueOf(wire.projectId()),String.valueOf(wire.serverId()),wire.repositoryUrl(),wire.branch(),wire.commitSha(),wire.runtime(),wire.applicationPort(),wire.publicPort(),wire.healthPath(),wire.imageTag(),wire.expiresAt(),false));}catch(Exception e){return Optional.empty();}} record Wire(int version,Long deploymentId,Long projectId,Long serverId,String repositoryUrl,String branch,String commitSha,String runtime,int applicationPort,int publicPort,String healthPath,String imageTag,Instant expiresAt,String nonce){} }
